// Terms / privacy acceptance logic (Shared/Legal.swift) against the real bundled
// Legal/legal.json (generated by tools/legal.py, a folder resource of this test bundle too).
import XCTest

final class LegalTests: XCTestCase {
    private var bundle: Bundle { Bundle(for: Self.self) }

    private func scratchDefaults() -> UserDefaults {
        let name = "hoppy.tests.legal." + UUID().uuidString
        let d = UserDefaults(suiteName: name)!
        d.removePersistentDomain(forName: name)
        return d
    }

    func testBundledTextsLoad() throws {
        let texts = try XCTUnwrap(LegalTexts.load(bundle: bundle), "Legal/legal.json missing or invalid")
        XCTAssertGreaterThan(texts.version.terms, 0)
        XCTAssertGreaterThan(texts.version.privacy, 0)
        for lang in ["it", "en"] {
            for key in ["title", "body", "updated_title", "updated_body", "accept_terms", "approve_clauses",
                        "read_privacy", "continue", "legal", "terms", "privacy", "licenses"] {
                XCTAssertNotEqual(texts.text(key, language: lang), key, "\(lang).\(key)")
            }
            for page in ["terms", "privacy", "licenses"] {
                let url = try XCTUnwrap(texts.page(page, bundle: bundle, language: lang), "\(page).\(lang)")
                XCTAssertTrue(url.isFileURL)
                XCTAssertEqual(url.deletingLastPathComponent().lastPathComponent, "Legal")
            }
        }
    }

    func testLanguage() {
        XCTAssertEqual(LegalTexts.language(["it-IT", "en-US"]), "it")
        XCTAssertEqual(LegalTexts.language(["en-GB", "it-IT"]), "en")
        XCTAssertEqual(LegalTexts.language(["de-DE"]), "en")
        XCTAssertEqual(LegalTexts.language([]), "en")
    }

    func testNeedsAcceptance() {
        let v1 = LegalVersion(terms: 1, privacy: 1)
        XCTAssertTrue(LegalConsent.needsAcceptance(bundled: v1, stored: nil))
        XCTAssertTrue(LegalConsent.needsAcceptance(bundled: nil, stored: v1), "missing texts fail closed")
        XCTAssertFalse(LegalConsent.needsAcceptance(bundled: v1, stored: v1))
        XCTAssertTrue(LegalConsent.needsAcceptance(bundled: LegalVersion(terms: 2, privacy: 1), stored: v1))
        XCTAssertTrue(LegalConsent.needsAcceptance(bundled: LegalVersion(terms: 1, privacy: 2), stored: v1))
        XCTAssertFalse(LegalConsent.needsAcceptance(bundled: v1, stored: LegalVersion(terms: 2, privacy: 2)))
    }

    func testAcceptStoresVersion() {
        let d = scratchDefaults()
        XCTAssertNil(LegalConsent.stored(d))
        XCTAssertFalse(LegalConsent.isUpdate(d))
        LegalConsent.accept(LegalVersion(terms: 3, privacy: 2), defaults: d)
        XCTAssertEqual(LegalConsent.stored(d), LegalVersion(terms: 3, privacy: 2))
        XCTAssertTrue(LegalConsent.isUpdate(d))
        XCTAssertTrue(LegalConsent.needsAcceptance(bundled: LegalVersion(terms: 4, privacy: 2), stored: LegalConsent.stored(d)))
    }
}
